-- words.sql — 完整词库表 (最终版)
-- 生成时间: 2026-11-04T14:03:17.873Z
-- 总词数: 4641
-- 字段: word/level/ipa/pos/meaning/examples/category/common/extended/pep_only/grade
-- 数据来源:
--   1. Oxford 3000 分级词库 (CEFR Pre-A1/A1/A2/B1/B2) — 级别划分参考
--   2. PEP 人教版分级词表 (cyforkk/pep-english-words, MIT)
--   3. 释义 / 音标 / 双语例句由本项目通过公开词典接口整理
-- 注：COCA 20k 扩展包 (src/data/extension.ts) 暂未并入，源文件保留待后续接入。

CREATE TABLE IF NOT EXISTS words (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  word TEXT NOT NULL UNIQUE,
  level TEXT NOT NULL,
  ipa TEXT NOT NULL DEFAULT '',
  pos TEXT NOT NULL DEFAULT '',
  meaning TEXT NOT NULL DEFAULT '',
  examples TEXT NOT NULL DEFAULT '[]',
  category TEXT,
  common INTEGER NOT NULL DEFAULT 0,
  extended INTEGER NOT NULL DEFAULT 0,
  pep_only INTEGER NOT NULL DEFAULT 0,
  grade TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_words_level ON words(level);
CREATE INDEX IF NOT EXISTS idx_words_category ON words(category);
CREATE INDEX IF NOT EXISTS idx_words_grade ON words(grade);
CREATE INDEX IF NOT EXISTS idx_words_common ON words(common);











