  ('artificial', 'B2', 'ˌɑːtɪˈfɪʃ(ə)l', 'adj.', 'adj. 人造的，人工的；人为的', '[{"en":"This food contains no artificial flavourings.","zh":"这种食品不含人工调味品。"},{"en":"The juice contains no artificial preservatives.","zh":"这种果汁不含人工防腐剂。"},{"en":"Most artificial joints are cemented into place.","zh":"绝大部分人造关节是被黏结复位的。"}]', 'thinking', 0, 0, 0, 'g11', 1793800997, 1793800997),
  ('artistic', 'B2', 'ɑːˈtɪstɪk', 'adj.', 'adj. 艺术的，艺术家的；有艺术鉴赏力的，有艺术天赋的', '[{"en":"She''s the artistic type.","zh":"她是艺术家一类的人。"},{"en":"She comes from a very artistic family.","zh":"她出身于艺术世家。"},{"en":"There are encouraging signs of an artistic revival.","zh":"有了鼓舞人心的艺术复兴的迹象。"}]', 'work', 0, 0, 0, 'g12', 1793800997, 1793800997),
  ('ashamed', 'B2', '/əˈʃeɪmd/', 'adj.', '感到羞耻的', '[{"en":"She was ashamed of her mistake.","zh":"她为自己的错误感到羞愧。"},{"en":"I am ashamed to say it.","zh":"说出来我很惭愧。"}]', 'emotions', 0, 0, 0, 'g11', 1793800997, 1793800997),
  ('aspect', 'B2', '/ˈæspekt/', 'n.', '方面', '[{"en":"We discussed every aspect.","zh":"我们讨论了各个方面。"},{"en":"This is an important aspect.","zh":"这是一个重要方面。"}]', 'thinking', 0, 0, 0, 'g11', 1793800997, 1793800997),
  ('assess', 'B2', '/əˈses/', 'v.', '评估', '[{"en":"We assessed the risk.","zh":"我们评估了风险。"},{"en":"The teacher assessed the work.","zh":"老师评估了作业。"}]', 'thinking', 0, 0, 0, 'g11', 1793800997, 1793800997),
  ('assessment', 'B2', 'əˈsesmənt', 'n.', 'n. 评估，评价；估价，估计', '[{"en":"He wrote a very generous assessment of my work.","zh":"他给我写的工作评价多有赞誉之词。"},{"en":"The government is rejigging some tax assessment methods.","zh":"政府正在调整一些税务评估方法。"},{"en":"The college has a highly formalized system of assessment.","zh":"这所学院有一套十分固定的评估体系。"}]', 'thinking', 0, 0, 0, 'g11', 1793800997, 1793800997),
  ('associate', 'B2', 'əˈsəʊsieɪt; əˈsəʊʃieɪt', 'v.', 'v. 联想，联系；支持，同意', '[{"en":"Mr. Lin is associate director of the Institute.","zh":"林先生是该研究所的副主任。"},{"en":"She didn''t want to associate with the likes of me.","zh":"她不想与我这种类型的人交往。"},{"en":"He will remain affiliated with the firm as a special associate director.","zh":"他会作为特别副主管，继续与这家公司保持联系。"}]', 'thinking', 0, 0, 0, 'g12', 1793800997, 1793800997),
  ('associated', 'B2', 'əˈsəʊsieɪtɪd; əˈsəʊʃieɪtɪd', 'adj.', 'adj. 有关联的，相关的；联合的，联营的', '[{"en":"Low oestrogen levels are associated with stress.","zh":"雌激素分泌水平低与精神压力有关。"},{"en":"Salaries and associated costs have risen substantially.","zh":"薪金与相关费用大大增加。"},{"en":"I haven''t been associated with the project over the last year.","zh":"我过去一年不曾跟这个项目有关联。"}]', 'thinking', 0, 0, 0, 'g12', 1793800997, 1793800997),
  ('association', 'B2', 'əˌsəʊsiˈeɪʃn; əˌsəʊʃiˈeɪʃn', 'n.', 'n. 协会，社团，联盟；交往，联合', '[{"en":"He has now become one of the patrons of the association.","zh":"他如今已成为该协会的名誉赞助人之一。"},{"en":"The trade association promotes ethical business practices.","zh":"这个贸易协会提倡合乎道德标准的商业行为。"},{"en":"Who is eligible to apply for membership of the association?","zh":"谁有资格申请加入这个协会？"}]', 'society', 0, 0, 0, 'g11', 1793800997, 1793800997),
  ('assume', 'B2', '/əˈsjuːm/', 'v.', '假定；承担', '[{"en":"I assume you are joking.","zh":"我想你是在开玩笑。"},{"en":"He assumed the role of leader.","zh":"他承担了领导角色。"}]', 'thinking', 0, 0, 0, 'g10', 1793800997, 1793800997),
  ('attempt', 'B2', '/əˈtempt/', 'v./n.', '尝试；企图', '[{"en":"He attempted to escape.","zh":"他试图逃跑。"},{"en":"It was a brave attempt.","zh":"那是一次勇敢的尝试。"}]', 'thinking', 0, 0, 0, 'g10', 1793800997, 1793800997),
  ('awkward', 'B2', '/ˈɔːkwəd/', 'adj.', '尴尬的；笨拙的', '[{"en":"The silence was awkward.","zh":"沉默令人尴尬。"},{"en":"He is awkward with tools.","zh":"他用工具很笨拙。"}]', 'emotions', 0, 0, 0, 'g10', 1793800997, 1793800997),
  ('bacteria', 'B2', 'bækˈtɪəriə', 'n.', 'n. 细菌（bacterium的复数）', '[{"en":"Chlorine is added to kill bacteria.","zh":"加入氯以杀菌。"},{"en":"The bacteria are harmless to humans.","zh":"这些细菌对人无害。"},{"en":"Warm milk is the ideal breeding ground for bacteria.","zh":"温牛奶是细菌理想的繁殖地。"}]', 'thinking', 0, 0, 0, 'g11', 1793800997, 1793800997),
  ('barrier', 'B2', '/ˈbæriə(r)/', 'n.', '障碍', '[{"en":"Language is a barrier.","zh":"语言是一种障碍。"},{"en":"They broke the barrier.","zh":"他们打破了障碍。"}]', 'thinking', 0, 0, 0, 'g11', 1793800997, 1793800997),
  ('basically', 'B2', 'ˈbeɪsɪkli', 'adv.', 'adv. 基本上，大体上；从根本上说，总的说来', '[{"en":"Yes, that''s basically correct.","zh":"对，基本正确。"},{"en":"People are basically the same the world over.","zh":"世界各地的人基本上都一样。"},{"en":"The official report basically exonerated everyone.","zh":"该官方报告基本洗脱了所有人的干系。"}]', 'thinking', 0, 0, 0, 'g12', 1793800997, 1793800997),
  ('beg', 'B2', 'beɡ', 'v.', 'v. 乞求，恳求；乞讨，行乞', '[{"en":"Cross decided to beg and wheedle a bit.","zh":"克罗斯决定小小地乞求和哄骗一下。"},{"en":"We are not going to beg for help anymore.","zh":"我们将不再请求帮助。"},{"en":"I managed to beg a lift from a passing motorist.","zh":"我设法求得一位开车路过的人让我搭车。"}]', 'thinking', 0, 0, 0, 'g10', 1793800997, 1793800997),
  ('being', 'B2', 'ˈbiːɪŋ', 'n.', 'n. 生物；存在', '[{"en":"I hate being photographed.","zh":"我讨厌被拍照。"},{"en":"I''m always being criticized.","zh":"我总是受到批评。"},{"en":"You''re just being paranoid.","zh":"你只是在疑神疑鬼。"}]', 'science', 1, 0, 0, 'g10', 1793800997, 1793800997),
  ('beneficial', 'B2', '/ˌbenɪˈfɪʃl/', 'adj.', '有益的', '[{"en":"Exercise is beneficial.","zh":"运动有益健康。"},{"en":"It is beneficial to all.","zh":"这对大家都有利。"}]', 'thinking', 0, 0, 0, 'g12', 1793800997, 1793800997),
  ('bent', 'B2', 'bent', 'adj.', 'adj. 弯曲的，变形的；驼背的', '[{"en":"She has a bent for mathematics.","zh":"她有数学天赋。"},{"en":"The knives were bent out of shape.","zh":"那些刀已经弯曲变形了。"},{"en":"He bent his head and kissed her.","zh":"他低下头吻了她。"}]', 'body', 0, 0, 0, 'g11', 1793800997, 1793800997),
  ('bet', 'B2', 'bet', 'v., n.', 'v. 打赌，赌博；<非正式>敢肯定', '[{"en":"I''ll bet they have yummy ice cream.","zh":"我打赌他们有好吃的冰激淋。"},{"en":"It''s a fair bet that they won''t turn up.","zh":"我敢打赌，他们不会出席。"},{"en":"What''s he like? I bet he''s really dreamy.","zh":"他长得如何？我敢说他一定很俊。"}]', 'thinking', 0, 0, 0, 'g10', 1793800997, 1793800997),
  ('beyond', 'B2', '/bɪˈjɒnd/', 'prep.', '超出；在……那一边', '[{"en":"The problem is beyond me.","zh":"这个问题我解决不了。"},{"en":"The house is beyond the hill.","zh":"房子在山的那一边。"}]', 'thinking', 0, 0, 0, 'g10', 1793800997, 1793800997),
  ('bitter', 'B2', 'ˈbɪtə(r)', 'adj.', 'adj. 味苦的；痛苦的，辛酸的', '[{"en":"The leaves taste rather bitter.","zh":"这些叶子尝起来相当苦。"},{"en":"He grimaced at the bitter taste.","zh":"他一尝那苦味，做了个怪相。"},{"en":"''Bitter'' and ''tears'' collocate.","zh":"bitter和tears可搭配使用。"}]', 'food', 0, 0, 0, 'g12', 1793800997, 1793800997),
  ('blame', 'B2', '/bleɪm/', 'v.', '责备；归咎于', '[{"en":"Don’t blame yourself.","zh":"别责怪自己。"},{"en":"They blamed the weather.","zh":"他们把原因归咎于天气。"}]', 'thinking', 0, 0, 0, 'g11', 1793800997, 1793800997),
  ('blind', 'B2', 'blaɪnd', 'adj.', 'adj. 失明的，盲的；未察觉的，视而不见的', '[{"en":"Mark has been blind from birth.","zh":"马克先天失明。"},{"en":"Doctors think he will go blind.","zh":"医生们认为他会失明。"},{"en":"He was a teacher of the blind.","zh":"他过去是位教盲人的老师。"}]', 'thinking', 0, 0, 0, 'g8', 1793800997, 1793800997),
  ('bond', 'B2', '/bɒnd/', 'n.', '纽带；债券', '[{"en":"The bond grew stronger.","zh":"纽带更牢固了。"},{"en":"They issued a bond.","zh":"他们发行了债券。"}]', 'thinking', 0, 0, 0, 'g12', 1793800997, 1793800997),
  ('boost', 'B2', '/buːst/', 'v.', '提升；推动', '[{"en":"The win boosted morale.","zh":"胜利鼓舞了士气。"},{"en":"It boosted the economy.","zh":"它推动了经济。"}]', 'actions', 0, 0, 0, 'g11', 1793800997, 1793800997),
  ('breast', 'B2', 'brest', 'n.', 'n. 乳房；胸部，胸脯', '[{"en":"Her mother died of breast cancer.","zh":"她母亲死于乳腺癌。"},{"en":"She developed a malignant breast tumour.","zh":"她得了恶性乳腺瘤。"},{"en":"There are many advantages to breast feeding.","zh":"母乳喂养的好处很多。"}]', 'body', 0, 0, 0, 'g12', 1793800997, 1793800997),
  ('brief', 'B2', '/briːf/', 'adj.', '简短的', '[{"en":"He gave a brief answer.","zh":"他作了简短的回答。"},{"en":"Let me be brief.","zh":"我长话短说。"}]', 'thinking', 0, 0, 0, 'g10', 1793800997, 1793800997),
  ('broad', 'B2', '/brɔːd/', 'adj.', '宽阔的', '[{"en":"The river is broad.","zh":"这条河很宽。"},{"en":"He has a broad smile.","zh":"他笑容开朗。"}]', 'size', 0, 0, 0, 'g10', 1793800997, 1793800997),
  ('broadcast', 'B2', 'ˈbrɔːdkɑːst', 'v., n.', 'v. 散布，传播（信息等）；播撒（种子等）', '[{"en":"The programme was broadcast nationally.","zh":"这个节目曾在全国播放过。"},{"en":"The speech was broadcast via a satellite link.","zh":"这次演讲是通过卫星播放的。"},{"en":"The concert will be broadcast live by the BBC.","zh":"这场音乐会将由英国广播公司实况转播。"}]', 'communication', 0, 0, 0, 'g12', 1793800997, 1793800997),
  ('budget', 'B2', '/ˈbʌdʒɪt/', 'n.', '预算', '[{"en":"We set a monthly budget.","zh":"我们制定了月度预算。"},{"en":"The project is over budget.","zh":"这个项目超出预算了。"}]', 'shopping', 0, 0, 0, 'g11', 1793800997, 1793800997),
  ('bullet', 'B2', 'ˈbʊlɪt', 'n.', 'n. 子弹，弹丸；（标示用的）黑圆点', '[{"en":"A bullet whizzed past my ear.","zh":"一颗子弹嗖的一声从我耳边飞过。"},{"en":"The bullet punctured the skull.","zh":"子弹射穿了头骨。"},{"en":"A bullet had grazed his arm.","zh":"一颗子弹擦过他的胳膊。"}]', 'thinking', 0, 0, 0, 'g12', 1793800997, 1793800997),
  ('bunch', 'B2', 'bʌntʃ', 'n.', 'n. 束，串，扎；一伙，一群', '[{"en":"They''re a great bunch of guys.","zh":"他们是一群很棒的小伙子。"},{"en":"She picked me a bunch of flowers.","zh":"她给我采了一束鲜花。"},{"en":"She was given a huge bunch of flowers.","zh":"有人给她送了一大束花。"}]', 'society', 0, 0, 0, 'g11', 1793800997, 1793800997),
  ('bush', 'B2', 'bʊʃ', 'n.', 'n. 灌木，灌木丛；荒野，丛林地带', '[{"en":"Luckily, a bush broke his fall.","zh":"幸亏有灌木接着，他摔得不重。"},{"en":"He snapped a twig off a bush.","zh":"他啪地从灌木上折下一小枝。"},{"en":"They used a machete to cut through the bush.","zh":"他们用大砍刀在灌木林中劈出了一条路。"}]', 'thinking', 0, 0, 0, 'g11', 1793800997, 1793800997),
  ('cable', 'B2', '/ˈkeɪbl/', 'n.', '电缆；缆绳', '[{"en":"The cable was cut.","zh":"电缆被切断了。"},{"en":"They crossed the river by cable car.","zh":"他们乘缆车过河。"}]', 'science', 0, 0, 0, 'g12', 1793800997, 1793800997),
  ('calculate', 'B2', '/ˈkælkjuleɪt/', 'v.', '计算', '[{"en":"He calculated the cost.","zh":"他计算了成本。"},{"en":"Can you calculate the total?","zh":"你能算出总数吗？"}]', 'thinking', 0, 0, 0, 'g12', 1793800997, 1793800997),
  ('cancel', 'B2', '/ˈkænsl/', 'v.', '取消', '[{"en":"The flight was cancelled.","zh":"航班被取消了。"},{"en":"I cancelled the meeting.","zh":"我取消了会议。"}]', 'thinking', 0, 0, 0, 'g9', 1793800997, 1793800997),
  ('cancer', 'B2', '/ˈkænsə(r)/', 'n.', '癌症', '[{"en":"He died of cancer.","zh":"他死于癌症。"},{"en":"Research on cancer continues.","zh":"癌症研究在持续进行。"}]', 'health', 0, 0, 0, 'g11', 1793800997, 1793800997),
  ('capable', 'B2', '/ˈkeɪpəbl/', 'adj.', '有能力的', '[{"en":"She is capable of the job.","zh":"她胜任这份工作。"},{"en":"He is a capable leader.","zh":"他是一位有能力的领导。"}]', 'thinking', 0, 0, 0, 'g10', 1793800997, 1793800997),
  ('capacity', 'B2', 'kəˈpæsəti', 'n.', 'n. 能力，才能；容积，容纳能力', '[{"en":"Human beings have an infinite capacity for self-deception.","zh":"人类自欺的能力是无穷尽的。"},{"en":"The school is filled to capacity.","zh":"这所学校已经满员。"},{"en":"He acted in an advisory capacity only.","zh":"他仅以顾问身份工作。"}]', 'thinking', 0, 0, 0, 'g12', 1793800997, 1793800997),
  ('capture', 'B2', '/ˈkæptʃə(r)/', 'v.', '捕获；占领', '[{"en":"They captured the criminal.","zh":"他们抓获了罪犯。"},{"en":"The photo captures the moment.","zh":"这张照片捕捉到了那一瞬间。"}]', 'thinking', 0, 0, 0, 'g12', 1793800997, 1793800997),
  ('cast', 'B2', 'kɑːst', 'n., v.', 'v. 投射（光，影）；将（视线，目光）投向', '[{"en":"The play has a very strong cast.","zh":"这部剧演员阵容强大。"},{"en":"The moon''s pale light cast soft shadows.","zh":"淡淡的月光投下柔和的暗影。"},{"en":"He has an unusual cast of mind.","zh":"他的思想与众不同。"}]', 'thinking', 0, 0, 0, 'g11', 1793800997, 1793800997),
  ('cell', 'B2', 'sel', 'n.', 'n. 细胞；小牢房', '[{"en":"Each cell of our bodies contains 46 chromosomes.","zh":"我们体内的每个细胞都有46条染色体。"},{"en":"Stem cell research is supported by many doctors.","zh":"干细胞研究得到很多医生的支持。"},{"en":"Sickle-cell anaemia is passed on through a recessive gene.","zh":"镰状细胞贫血通过隐性基因遗传给后代。"}]', 'science', 0, 0, 0, 'g11', 1793800997, 1793800997),
  ('chairman', 'B2', 'ˈtʃeəmən', 'n.', 'n. （尤指男性）主席，（委员会或组织的）负责人；（公司）总裁，（组织）主席', '[{"en":"He was an admirable chairman.","zh":"他是位值得尊敬的主席。"},{"en":"I propose Tom Ellis for chairman.","zh":"我提名汤姆•埃利斯做主席。"},{"en":"As chairman, I must remain impartial.","zh":"作为主席，我必须保持中立。"}]', 'work', 0, 0, 0, 'g10', 1793800997, 1793800997),
  ('characteristic', 'B2', 'ˌkærəktəˈrɪstɪk', 'n., adj.', 'n. 特征，特点，特色', '[{"en":"She spoke with characteristic enthusiasm.","zh":"她说话带着特有的热情。"},{"en":"He replied with characteristic insouciance: \"So what?\"","zh":"他用特有的漫不经心的口吻答道：“那又怎么样？”"},{"en":"The main characteristic of the strike has been its longevity.","zh":"这次罢工的主要特点是持续时间长。"}]', 'thinking', 0, 0, 0, 'g11', 1793800997, 1793800997),
  ('chief', 'B2', '/tʃiːf/', 'adj.', '主要的；首席的', '[{"en":"The chief reason is cost.","zh":"主要原因是成本。"},{"en":"He is the chief engineer.","zh":"他是总工程师。"}]', 'thinking', 0, 0, 0, 'g10', 1793800997, 1793800997),
  ('circumstance', 'B2', 'ˈsɜːkəmstəns', 'n.', 'n. 条件，情况，环境；境况，经济状况', '[{"en":"I know I can trust her in any circumstance.","zh":"我知道我在任何情况下都能信任她。"},{"en":"In every moment and every circumstance, you can choose to have fuller, richer life by setting a clear intention.","zh":"在任何时刻、在任何情况下，你都可以通过设定一个明确的目标来选择更充实、更丰富的生活。"},{"en":"It is their sensitive response to human circumstance that accounts for the persistence of certain universal ideas.","zh":"他们对人类环境的敏感反应解释了某些普遍观点的持久性。"}]', 'nature', 0, 0, 0, 'g11', 1793800997, 1793800997);
INSERT INTO words (word, level, ipa, pos, meaning, examples, category, common, extended, pep_only, grade, created_at, updated_at) VALUES
  ('cite', 'B2', 'saɪt', 'v.', 'v. 引用，援引；引证，引以为例', '[{"en":"Can you cite another case like this?","zh":"你能举另外一个像这样的实例吗？"},{"en":"It would be an endless task to cite such living examples.","zh":"这样的实例举不胜举。"},{"en":"The third rule is to be ready to cite options and consequences.","zh":"第三条规则是准备好列举选项和结果。"}]', 'thinking', 0, 0, 0, 'g11', 1793800997, 1793800997),
  ('citizen', 'B2', '/ˈsɪtɪzn/', 'n.', '公民；市民', '[{"en":"He is a British citizen.","zh":"他是英国公民。"},{"en":"Citizens must obey the law.","zh":"公民必须遵守法律。"}]', 'society', 0, 0, 0, 'g12', 1793800997, 1793800997),
  ('civil', 'B2', '/ˈsɪvl/', 'adj.', '民事的；公民的；礼貌的', '[{"en":"They reached a civil agreement.","zh":"他们达成了民事协议。"},{"en":"Be civil to strangers.","zh":"对陌生人要有礼貌。"}]', 'thinking', 0, 0, 0, 'g12', 1793800997, 1793800997),
  ('classic', 'B2', '/ˈklæsɪk/', 'adj./n.', '经典的；名著', '[{"en":"It is a classic novel.","zh":"这是一部经典小说。"},{"en":"He enjoys the classics.","zh":"他喜欢经典作品。"}]', 'thinking', 0, 0, 0, 'g8', 1793800997, 1793800997),
  ('closely', 'B2', 'ˈkləʊsli', 'adv.', 'adv. 仔细地，严密地；（联系）紧密地', '[{"en":"He closely guarded her identity.","zh":"他严密地保守她的身份。"},{"en":"These problems are closely related.","zh":"这些问题都是密切相关的。"},{"en":"Our defence had him closely marked.","zh":"我方后卫已经紧紧地盯住了他。"}]', 'society', 0, 0, 0, 'g12', 1793800997, 1793800997),
