  ('humour', 'B2', '/ˈhjuː.mə(ɹ)/', 'n.', 'n. 幽默，幽默感；感觉，心情', '[{"en":"He had a puckish sense of humour.","zh":"他有种爱搞怪的幽默感。"},{"en":"He had a clownish sense of humour.","zh":"他有着滑稽的幽默感。"},{"en":"Jane has a wicked sense of humour.","zh":"简有一种恶作剧的幽默感。"}]', 'emotions', 0, 0, 0, 'g12', 1793800997, 1793800997),
  ('hunting', 'B2', '/ˈhʌntɪŋ/', 'n.', 'n. 打猎，狩猎；搜寻，寻找', '[{"en":"Police are hunting his killer.","zh":"警方正在追捕杀害他的凶手。"},{"en":"I am against hunting in any form.","zh":"我反对任何形式的狩猎。"},{"en":"Police are hunting an escaped criminal.","zh":"警察正在追捕一名逃犯。"}]', 'actions', 0, 0, 0, 'g12', 1793800997, 1793800997),
